<?php require_once __DIR__.'/../includes/functions.php';require_admin();$hero=db()->query('SELECT * FROM hero ORDER BY id DESC LIMIT 1')->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();db()->prepare('UPDATE hero SET title=?,subtitle=?,description=?,cta_text=?,cta_url=?,video_url=?,fallback_image=?,background_color=?,video_enabled=?,animation_speed=? WHERE id=?')->execute([$_POST['title'],$_POST['subtitle'],$_POST['description'],$_POST['cta_text'],$_POST['cta_url'],$_POST['video_url'],$_POST['fallback_image'],$_POST['background_color'],isset($_POST['video_enabled'])?1:0,$_POST['animation_speed'],$hero['id']]);flash('success','تم تحديث واجهة الموقع.');header('Location: '.base('admin/hero.php'));exit;}$adminTitle='مدير الواجهة الرئيسية';include 'header.php';?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div><label>العنوان</label><input name="title" value="<?=e($hero['title'])?>"></div><div><label>العنوان الصغير</label><input name="subtitle" value="<?=e($hero['subtitle'])?>"></div><div><label>نص الزر</label><input name="cta_text" value="<?=e($hero['cta_text'])?>"></div><div><label>الرابط</label><input name="cta_url" value="<?=e($hero['cta_url'])?>"></div><div><label>رابط الفيديو (MP4/WebM/YouTube/CDN)</label><input name="video_url" value="<?=e($hero['video_url'])?>"></div><div><label>صورة بديلة</label><input name="fallback_image" value="<?=e($hero['fallback_image'])?>"></div><div><label>الخلفية</label><input name="background_color" value="<?=e($hero['background_color'])?>"></div><div><label>سرعة الحركة</label><input type="number" name="animation_speed" value="<?=e($hero['animation_speed'])?>"><label><input type="checkbox" name="video_enabled" <?=$hero['video_enabled']?'checked':''?>> تفعيل الفيديو</label></div><div class="full"><label>الوصف</label><textarea name="description"><?=e($hero['description'])?></textarea></div><button class="button gold">حفظ الواجهة</button></form><?php include 'footer.php';?>
